import{_ as o,C as n,o as i,c as r,a5 as a,E as s}from"./chunks/framework.BwlBv862.js";const m=JSON.parse('{"title":"Diagnose a failed operation","description":"","frontmatter":{"title":"Diagnose a failed operation","docId":"user.preferences.troubleshooting","translationKey":"user.preferences.troubleshooting","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"40d8c5706363baa28e4114397696c8c2adb320843271a00efb3772be0322d5e2","translationRevision":"40d8c5706363baa28e4114397696c8c2adb320843271a00efb3772be0322d5e2","order":30},"headers":[],"relativePath":"en/user/preferences/troubleshooting.md","filePath":"en/user/preferences/troubleshooting.md","lastUpdated":1794611623000}'),l={name:"en/user/preferences/troubleshooting.md"};function c(d,e,p,u,h,f){const t=n("DemoFrame");return i(),r("div",null,[e[0]||(e[0]=a('<h1 id="diagnose-a-failed-operation" tabindex="-1">Diagnose a failed operation <a class="header-anchor" href="#diagnose-a-failed-operation" aria-label="Permalink to &quot;Diagnose a failed operation {#diagnose-a-failed-operation}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Identify the failing component and collect a useful report without repeatedly triggering effects. You need the app version, the approximate failure time and the operation you attempted. Keep a <a href="./backups.html">backup</a> before resets or data replacement.</p><h2 id="inspect-the-nearest-evidence" tabindex="-1">Inspect the nearest evidence <a class="header-anchor" href="#inspect-the-nearest-evidence" aria-label="Permalink to &quot;Inspect the nearest evidence {#inspect-the-nearest-evidence}&quot;">​</a></h2><ol><li>Read the inline error where the failure occurred. Use its diagnostic status action, or open <strong>Diagnostics</strong>, to inspect related entries.</li><li>Filter by source, level or text. Useful sources include LIVE, monitoring, plugins, account, synchronization, updates, transport, catalog, installation and collaboration.</li><li>Select the relevant entry and retain its time, code, request/entity identifiers and short description. Expand details when available.</li><li>Copy the filtered diagnostics or export the text report. If clipboard/export fails, use the displayed fallback text. Review it before sharing; remove private tokens, cookies, invitation links and personal content.</li><li>Include a short reproduction: page, selected creator/profile/plugin, action taken, expected result and actual result. Explain whether it happened before or after an update.</li></ol><h2 id="isolate-common-failures" tabindex="-1">Isolate common failures <a class="header-anchor" href="#isolate-common-failures" aria-label="Permalink to &quot;Isolate common failures {#isolate-common-failures}&quot;">​</a></h2><p>For an empty feed, clear search and filters, resume scrolling and confirm the <a href="./../live/connections.html">connection</a>. Paused scrolling is not disconnection. A display loss indicator does not prove points or analytics lost the same event.</p><p>For an automation with no run, check active profile, event/action enablement, trigger, filter field paths and cooldown. Inspect run history before changing effects. <strong>Test</strong> can execute audio, HTTP, points and plugin actions.</p><p>For a plugin failure, read the installation job or connection error. For Cloud, check account state and the affected area rather than replacing a TikTok cookie. For overlays, inspect gateway status and source configuration. For updates, use <a href="./../updates.html">manual update guidance</a> when installation is unavailable.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>Diagnostics filtering, copying and text export are available. A packaged app also needs its web assets and platform runtime. On Linux, check the supported GTK/WebKitGTK environment and X11/XWayland session; on Windows, check WebView2. See <a href="./../requirements.html">requirements</a> for installation scope.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery {#recovery}&quot;">​</a></h2><p>Retry after correcting the specific cause. For revision conflicts, reload and review the current saved state. For an unconfirmed remote command, inspect its journal/status before sending another: a timeout can follow a successful effect. If startup fails, report the package/version and startup log rather than deleting the data directory.</p>',13)),s(t,{scenario:"diagnostics",locale:"en",tour:"diagnostics",title:"Demo: diagnostics"}),e[1]||(e[1]=a('<h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details {#operational-details}&quot;">​</a></h2><p>Diagnostics is an in-memory UI log, limited to 2,000 entries or 2 MiB. Repeated entries within five seconds are grouped. The view initially shows 100; export includes all matching filtered entries, whereas <strong>Clear</strong> deletes the whole log. Copy/export evidence before closing, restarting, clearing, or switching/signing out of a known Cloud account: those account changes clear this UI history.</p><p>If no window opens, inspect native <code>tiktools.log</code> (controller mode: <code>controller.log</code>) in <code>%LOCALAPPDATA%/TikTools/logs</code> on Windows or <code>${XDG_DATA_HOME:-~/.local/share}/TikTools/logs</code> on Linux. <code>TIKTOOLS_HOME</code> changes the root and <code>TIKTOOLS_LOG_DIR</code> overrides the log directory. If logging itself failed, the file may not exist; retain a terminal/startup error when available. Native logs are not guaranteed to have UI redaction: review all exports before sharing.</p>',3))])}const b=o(l,[["render",c]]);export{m as __pageData,b as default};
